add("IN3", "Tableurs et analyse de données commerciales", "Informatique", ["BTS1"],
[
 "Un tableur organise les données en lignes et colonnes et permet de les trier, filtrer, calculer et représenter graphiquement.",
 "Une référence absolue (avec $) reste fixe lors d'une copie de formule ; une référence relative suit le déplacement de la cellule.",
 "Les fonctions usuelles du commerce sont SOMME, MOYENNE, NB.SI, SOMME.SI, EQUIV et INDEX, ainsi que les tableaux croisés dynamiques.",
 "Un tableau croisé dynamique (TCD) agrège rapidement les ventes par produit, par client, par commercial ou par période.",
 "La formule de base d'une marge est (prix de vente − coût) / prix de vente pour le taux commercial, ou marge / coût pour le taux sur coût.",
 "SI permet de construire un calcul conditionnel, par exemple appliquer une remise selon le volume commandé.",
 "La mise en forme conditionnelle met en évidence les valeurs hors seuil : retards, marges négatives, dépassements de budget.",
 "Un graphique doit choisir un type adapté : histogramme pour comparer des valeurs, courbe pour suivre une évolution, camembert pour des parts relatives.",
 "La qualité d'une analyse dépend de la propreté de la source : colonnes homogènes, dates au format date, pas de lignes vides ni de doublons.",
 "Les données personnelles contenues dans un tableur doivent être protégées : mot de passe du fichier, droits d'accès et stockage conforme.",
 "En BTS NDRC, le tableur sert à préparer une prospection, chiffrer une offre et suivre les indicateurs de l'activité commerciale.",
 "Exemple : un TCD croisant commercial et mois affiche le chiffre de chaque vendeur et permet de repérer immédiatement un écart à l'objectif.",
],
Q(
 ("Quelle référence reste fixe lors d'une copie de formule ?", ["La référence relative", "La référence absolue avec $", "Le nom de la feuille", "Le titre de la colonne"], 1,
  "Le symbole $ fige la ligne ou la colonne : la référence absolue ne bouge pas quand on copie la formule."),
 ("Quelle fonction additionne les valeurs d'une plage ?", ["NB.SI", "SOMME", "EQUIV", "MOYENNE"], 1,
  "SOMME additionne une plage ; MOYENNE calcule la moyenne, NB.SI compte selon un critère."),
 ("À quoi sert un tableau croisé dynamique ?", ["À dessiner un logo", "À agréger les données selon plusieurs critères", "À envoyer des e-mails", "À créer un mot de passe"], 1,
  "Le TCD synthétise rapidement les données par produit, période, commercial ou client."),
 ("Comment calculer un taux de marge commerciale ?", ["Marge / coût", "Marge / prix de vente", "Prix / marge", "Coût / prix"], 1,
  "Le taux de marge commerciale rapporte la marge au prix de vente HT."),
 ("Quel graphique montre une évolution dans le temps ?", ["Le camembert", "La courbe", "Le nuage de points", "L'histogramme"], 1,
  "La courbe relie les valeurs successives dans le temps ; l'histogramme compare des catégories."),
 ("Que permet la mise en forme conditionnelle ?", ["De supprimer les doublons", "De colorer les valeurs selon une règle", "De changer la langue", "D'envoyer un rapport"], 1,
  "Elle applique automatiquement un style aux cellules qui satisfont une condition, par exemple marge négative."),
 ("Quelle source produit une analyse fiable ?", ["Des colonnes homogènes et des dates au format date", "Des lignes vides régulières", "Des doublons nombreux", "Des textes libres dans les colonnes numériques"], 0,
  "La propreté de la source est une condition de fiabilité : types cohérents et absence de doublons."),
 ("Quelle précaution s'impose avec un tableur contenant des clients ?", ["Le laisser sur un poste partagé sans mot de passe", "Protéger le fichier et limiter les accès", "Le publier sur le web", "Supprimer les sauvegardes"], 1,
  "Les fichiers contenant des données personnelles doivent être protégés et stockés de façon conforme."),
 ("Distinguer référence relative et référence absolue et donner un cas d'usage de chacune.",
  "Une référencerelative (A1) s'ajuste lorsqu'on copie la formule : elle convient pour appliquer le même calcul à chaque ligne. Une référence absolue ($A$1) reste fixe : elle convient pour un taux, un seuil ou un coefficient unique placé dans une cellule et réutilisé partout. Les formes mixtes ($A1 ou A$1) figent seulement une des deux dimensions.",
  "On explique le comportement à la copie et on donne un exemple pour chaque type."),
 ("Un tableur contient 240 ventes, un prix moyen de 50 € HT et un coût moyen de 32 €. Calculer le chiffre, la marge totale et le taux de marge commerciale.",
  "Chiffre = 240 × 50 = 12 000 € HT. Marge unitaire = 50 − 32 = 18 €, marge totale = 240 × 18 = 4 320 €. Taux de marge commerciale = 4 320 / 12 000 = 36 %. Ces calculs correspondent à une formule = (prix − coût) / prix reproduite sur toutes les lignes puis agrégée avec SOMME.",
  "On calcule le chiffre, la marge unitaire, la marge totale et le taux, puis on relie au tableur."),
),
(
 "L'idée en une phrase|Un tableur fiable ne se juge pas à la beauté de son graphique mais à la propreté de ses données et à la justesse de ses formules.",
 "Formules clés|= SOMME(plage) · = NB.SI(plage; critère) · = SOMME.SI(plage; critère; plage2)|Taux commercial = marge / prix ; taux sur coût = marge / coût.",
 "[['Fonction', 'Usage', 'Exemple'], ['SOMME', 'Additionner', 'Chiffre total'], ['NB.SI', 'Compter selon critère', 'Nombre de clients'], ['SOMME.SI', 'Additionner selon critère', 'Ventes par produit'], ['EQUIV', 'Trouver une position', 'Ligne du client']]",
 "['Nettoyer les donnees source', 'Ecrire les formules avec les bonnes references', 'Verifier quelques lignes a la main', 'Construire le TCD', 'Choisir un graphique adapte']",
 "['Saisir les ventes dans un tableau propre', 'Convertir les dates en format date', 'Calculer les marges ligne par ligne', 'Croiser les donnees par produit et mois', 'Representer les ecarts a l objectif']",
 "['Oublier le $ sur un taux unique', 'Additionner des cellules texte', 'Laisser des lignes vides dans la plage', 'Choisir un camembert pour une evolution', 'Partager le fichier sans protection']",
 "['240 × 50 € = 12 000 € de chiffre', 'Marge unitaire 50 − 32 = 18 €', 'Marge totale = 4320 €', 'Taux commercial = 4320 / 12000 = 36 %', 'Taux sur cout = 18 / 32 = 56,25 %']",
), st=("Fonctions utiles", "Analyser les ventes", "Tableur fiable / piège"))

